    "type": "mecquoise",
    "versets_count": 109,
    "theme": "La patience face au déni : les hommes qui réclament d'autres signes, la vie d'ici-bas comme une eau éphémère, Noé et Moïse face à leurs peuples, et le peuple de Jonas — le seul dont la foi tardive profita",
    "note_pedagogique": "Nommée d'après Jonas, dont le peuple est l'unique exception de l'histoire prophétique : ayant cru avant que le châtiment ne s'abatte, il fut épargné (v.98). La sourate déroule la question de la foi et du délai : pourquoi Dieu n'exauce-t-il pas les pressés ? Elle culmine sur la noyade de Pharaon et la parole terrible : « Aujourd'hui Nous sauvons ton corps, pour que tu sois un signe. »",
