      "ar": "أُوْلَـٰئِكَ مَأْوَىٰهُمُ النَّارُ بِمَا كَانُواْ يَكْسِبُونَ",
      "translit": "Ūlāʾika maʾwāhumu n-nāru bimā kānū yaksibūn",
