    "declic_frequence": "āmana (croire, racine أ-م-ن) est mis à l'épreuve du temps dans cette sourate : quand la foi sert-elle encore ? Pharaon croit au moment de se noyer — āmantu, « je crois ! » (v.90) — et s'entend répondre : āl-āna, « maintenant ?! Alors que tu as désobéi auparavant ? » Trop tard. Mais le peuple de Jonas (v.98) crut avant l'échéance, et sa foi lui profita : unique exception de l'histoire. La leçon : l'īmān n'est pas un mot de la dernière heure mais un engagement pendant qu'il est encore temps — la porte est ouverte, pas éternellement."
